import { test, expect } from '@playwright/test';

test.describe('Google Account Connection to User Profile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
  });

  test('should successfully connect Google account and update profile with user details', async ({ page }) => {
    // Verify profile page loads
    const profileHeader = page.getByRole('heading', { name: /profile/i });
    await expect(profileHeader).toBeVisible();

    // Click Google connect button
    const connectButton = page.getByRole('button', { name: /connect google/i });
    await expect(connectButton).toBeVisible();
    await connectButton.click();

    // Verify Google authentication modal appears
    const authModal = page.locator('[data-testid="google-auth-modal"]');
    await expect(authModal).toBeVisible();

    // Click sign in with Google
    const signInButton = page.getByRole('button', { name: /sign in with google/i });
    await expect(signInButton).toBeVisible();
    await signInButton.click();

    // Verify Google sign-in page loads
    const googleSignInPage = page.locator('[data-testid="google-sign-in-page"]');
    await expect(googleSignInPage).toBeVisible();

    // Mock successful Google authentication response
    await page.route('**/api/auth/google/token', route => {
      route.continue();
    });

    // Click sign in button on Google page
    const googleSignInBtn = page.getByRole('button', { name: /sign in/i });
    await googleSignInBtn.click();

    // Wait for profile to update
    await page.waitForResponse(response => 
      response.url().includes('/api/auth/google/token') && response.status() === 200
    );

    // Verify profile is updated with Google user details
    const userName = page.getByText(/john doe/i);
    await expect(userName).toBeVisible();

    const userEmail = page.getByText(/john.doe@example.com/i);
    await expect(userEmail).toBeVisible();

    const profileAvatar = page.locator('[data-testid="profile-avatar"]');
    await expect(profileAvatar).toHaveAttribute('src', /google-avatar/);

    // Verify connection status message
    const connectedStatus = page.getByText(/connected with google/i);
    await expect(connectedStatus).toBeVisible();
  });

  test('should handle Google authentication failure and display error message', async ({ page }) => {
    // Verify profile page loads
    const profileHeader = page.getByRole('heading', { name: /profile/i });
    await expect(profileHeader).toBeVisible();

    // Click Google connect button
    const connectButton = page.getByRole('button', { name: /connect google/i });
    await expect(connectButton).toBeVisible();
    await connectButton.click();

    // Verify Google authentication modal appears
    const authModal = page.locator('[data-testid="google-auth-modal"]');
    await expect(authModal).toBeVisible();

    // Mock failed Google authentication response
    await page.route('**/api/auth/google/token', route => {
      route.abort('failed');
    });

    // Click sign in button on Google page
    const googleSignInBtn = page.getByRole('button', { name: /sign in/i });
    await googleSignInBtn.click();

    // Wait for error state
    await page.waitForTimeout(500);

    // Verify error message is displayed
    const errorMessage = page.getByText(/failed to connect with google/i);
    await expect(errorMessage).toBeVisible();

    // Verify connect button is still visible for retry
    const retryButton = page.getByRole('button', { name: /try again/i });
    await expect(retryButton).toBeVisible();

    // Verify profile details are not updated
    const userName = page.getByText(/john doe/i);
    await expect(userName).not.toBeVisible();

    // Verify connection status shows error
    const connectionStatus = page.getByText(/connection failed/i);
    await expect(connectionStatus).toBeVisible();
  });
});
